// Claude's review tests for A34 (code-mock hints, the Try URL, and draft runs). agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { codeCompletions, paramNamesOf, sampleUrl } from './codeHints';

const labels = (r: ReturnType<typeof codeCompletions>) => r?.options.map((o) => o.label) ?? null;

describe('paramNamesOf', () => {
  it('reads :names and *wildcards, not a host port', () => {
    expect(paramNamesOf('/api/users/:id/orders/:orderId')).toEqual(['id', 'orderId']);
    expect(paramNamesOf('/files/*rest')).toEqual(['rest']);
    expect(paramNamesOf('http://localhost:8080/api/:id')).toEqual(['id']);
    expect(paramNamesOf('/api/plain')).toEqual([]);
    expect(paramNamesOf('/v1\\:batch/:id')).toEqual(['id']);
  });
});

describe('sampleUrl', () => {
  it('fills params with 1 and wildcards with a/b, on the page origin', () => {
    expect(sampleUrl('/api/users/:id', 'http://localhost:3000')).toBe('http://localhost:3000/api/users/1');
    expect(sampleUrl('/files/*rest', 'http://localhost:3000')).toBe('http://localhost:3000/files/a/b');
    expect(sampleUrl('/api/:a/x/:b', '')).toBe('/api/1/x/1');
  });
  it('keeps a host the pattern names', () => {
    expect(sampleUrl('https://api.shop.test/v1/:id', 'http://localhost:3000')).toBe('https://api.shop.test/v1/1');
  });
  it('turns an escaped character back into itself', () => {
    expect(sampleUrl('/v1\\:batch', 'http://h.test')).toBe('http://h.test/v1:batch');
  });
});

describe('codeCompletions', () => {
  const params = ['id', 'orderId'];
  it('after req. offers the request fields, from the start of the word', () => {
    const text = 'return req.';
    const r = codeCompletions(text, params);
    expect(r?.from).toBe(text.length);
    expect(labels(r)).toEqual(['method', 'url', 'path', 'params', 'query', 'headers', 'body', 'bodyText', 'callCount']);
    expect(r!.options.every((o) => o.detail.length > 0)).toBe(true);
    const partial = codeCompletions('return req.pa', params);
    expect(partial?.from).toBe('return req.'.length);
  });
  it('after res. offers status, headers and delayMs', () => {
    expect(labels(codeCompletions('res.', params))).toEqual(['status', 'headers', 'delayMs']);
  });
  it('after req.params. or params. offers the pattern names', () => {
    expect(labels(codeCompletions('const x = req.params.', params))).toEqual(['id', 'orderId']);
    expect(labels(codeCompletions('if (params.o', params))).toEqual(['id', 'orderId']);
    expect(codeCompletions('params.', [])).toBeNull();
  });
  it('a bare word offers the top-level names', () => {
    const r = codeCompletions('  return q', params);
    expect(r?.from).toBe('  return '.length);
    expect(labels(r)).toEqual(['req', 'res', 'params', 'query', 'body']);
  });
  it('nothing after an unknown object, or right after a space, or inside a string', () => {
    expect(codeCompletions('foo.', params)).toBeNull();
    expect(codeCompletions('return ', params)).toBeNull();
    expect(codeCompletions("const s = 'req.", params)).toBeNull();
  });
});
